import React,{useState} from "react";
import {
  Container,
  Heading,
  Box,
  Text,
  Link as ChakraLink,
} from "@chakra-ui/react";
import { Link, navigate } from 'gatsby';

type LayoutProps = {
  children: React.ReactNode;
  matrix?: boolean;
};

export const Layout: React.FC<LayoutProps> = ({ children, matrix = false }) => {
  const [blur,setBlur]=useState(false)

  return (
    <Container
      maxW={matrix ? "100%" : "container.xl"}
      width="100%"
      minH={matrix ? "100vh" : undefined}
      px={matrix ? { base: 4, md: 8 } : undefined}
      bg={matrix ? "#070708" : undefined}
      color={matrix ? "#e6e6e8" : undefined}
    >
      <Box
        mt={matrix ? 0 : 5}
        py={matrix ? 3 : undefined}
        display={"flex"}
        flexDirection={{base:'column',md:'row'}}
        justifyContent={{base:'center',md:"space-between"}}
        alignItems={{base:'center',md:'space-between'}}
        alignSelf={"flex-end"}
      >
        <Heading fontSize={"2xl"} as={Link} to={'/'} mb={{base:'20px',md:0}} color={matrix ? "#f2f2f2" : undefined}>William Melo</Heading>
        <Box color={matrix ? "#cf3845" : "secondary.500"} fontWeight={"700"}>
          <ChakraLink onMouseOver={()=>setBlur(!blur)} onMouseOut={()=>setBlur(false)}  onMouseDown={()=>setBlur(false)} onMouseUp={()=>setBlur(false)}  onClick={()=>setBlur(false)} as={Link} to={'/about'} _hover={{ color: matrix ? "#f2f2f2" : "black" }}>ABOUT ME</ChakraLink>
          <ChakraLink   onMouseOver={()=>setBlur(!blur)} onMouseOut={()=>setBlur(false)}  onClick={()=>setBlur(false)}  as={Link} to={'/proyects'} ml={5} _hover={{ color: matrix ? "#f2f2f2" : "black" }}>
            PROJECTS
          </ChakraLink>
        </Box>
      </Box>
      <Container   style={{ filter: !matrix && blur ? "blur(2px)":"blur(0px)" }} px={matrix ? 0 : {base:0,md:'16px'}}  maxW={matrix ? "container.xl" : "container.md"}>
      {children}
      </Container>
    </Container>
  );
};
